            if g[r][c] != 7:
                color = g[r][c]
                a = c
                while c + 1 < w and g[r][c + 1] == color:
                    c += 1
                ans.append((a, c, color))
            c += 1
        return ans

    def left_run(r):
        rr = runs(r)
        return rr[0] if rr else None

    # Complete the alternating left and outer-right joins.
    for r in range(1, h - 1, 2):
        a, b = left_run(r - 1), left_run(r + 1)
        if a and b and a[2] == b[2]:
            g[r][0] = 7
            if g[r - 1][-1] == g[r + 1][-1] == g[r][-1] == 7:
                g[r][-1] = 6

    # Complete diagonal joins between different left-hand strokes.
    for r in range(1, h - 1, 2):
        a, b = left_run(r - 1), left_run(r + 1)
        if a and b and a[2] != b[2] and b[0] == 2:
            x = max(a[1], b[1])
            if x < w and g[r][x] == 7:
                # A vertical stroke elsewhere on the right can instead be the
                # connection; only use the left join when it is the next slot.
                if b[1] >= a[1] and b[1] - a[1] <= 2:
                    g[r][x] = 6

    # Close repeated right-hand U shapes and two-column diagonal steps.
    for r in range(1, h - 1, 2):
        above = runs(r - 1)
        below = runs(r + 1)
        if len(above) >= 2 and len(below) >= 2:
            ar, br = above[-1], below[-1]
            if ar == br and all(g[r][c] == 7 for c in range(ar[0], ar[1] + 1)):
                if ar[1] + 1 < w and g[r][ar[1] + 1] == 7:
                    g[r][ar[1] + 1] = 6
            elif ar[2] == br[2] and ar[1] == br[1]:
